import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitLoss; // Positive for profit, negative for loss

  Transaction({required this.coinName, required this.datetime, required this.profitLoss});
}

Future<Map<String, double>> analyzeProfitsLosses(List<Transaction> transactions) async {
  // Group transactions by coin and calculate average profit/loss per coin
  final groupedTransactions = transactions.groupBy((t) => t.coinName);
  final avgProfits = <String, double>{};
  final avgLosses = <String, double>{};

  for (final entry in groupedTransactions.entries) {
    final coinName = entry.key;
    final coinTransactions = entry.value.toList(); // Extract transactions for this coin

    double totalProfit = 0;
    for (final transaction in coinTransactions) {
      totalProfit += transaction.profitLoss;
    }
    final avgProfit = totalProfit / coinTransactions.length;
    avgProfits[coinName] = avgProfit;

    avgLosses[coinName] = -avgProfit; // Use negated value for loss ranking
  }

  // Find top 3 highest avg profits and losses
  final sortedProfits = avgProfits.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));
  final top3Profits = Map.fromEntries(sortedProfits.sublist(0, 3));

  final sortedLosses = avgLosses.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));
  final top3Losses = Map.fromEntries(sortedLosses.sublist(0, 3));

  return {
    "topProfits": top3Profits,
    "topLosses": top3Losses,
  };
}

// Example Usage (assuming you have your transaction list 'transactions'):
analyzeProfitsLosses(transactions).then((result) {
  print("Top 3 Profitable Coins: ${result['topProfits']}");
  print("Top 3 Loss-Making Coins: ${result['topLosses']}");
});
```

