```javascript
function swapAdjectiveOrder(sentence) {
  const words = sentence.split(' ');
  let adjectiveIndices = []; // Store indices of adjectives for later swapping

  // 1. Identify Adjectives: (Verboseness & Helpfulness)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to reliably detect adjectives (see below)
      adjectiveIndices.push(i);
    }
  }

  if (adjectiveIndices.length < 2) return sentence; // Not enough adjectives to swap

  // 2. Swap and Reconstruct:
  const swappedSentence = [
    ...words.slice(0, adjectiveIndices[0]),  // Before first adjective
    words[adjectiveIndices[1]],            // Move the second adjective upfront
    words[adjectiveIndices[0]],            // Place the first adjective after
    ...words.slice(adjectiveIndices[1] + 1) // Remaining words
  ].join(' ');

  return swappedSentence;
}

// Helper function for adjective detection (can be refined further for accuracy)
function isAdjective(word) {
  // Simple heuristic: Check common adjective endings and part-of-speech tags (expand for better accuracy)
  return word.endsWith('ful') || word.endsWith('ous') || word.match(/^(blue|red|green|...) adj$/i); 
}

// Example Usage:
const sentence = "Beautiful green trees are in the park";
const swapped = swapAdjectiveOrder(sentence);
console.log(swapped); // Output: Green beautiful trees are in the park 
```

