   import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
   import { Document, Types } from 'mongoose';

   // Define nested schema for 'ProductReviews' (example)
   interface ProductReview {
     rating: number;
     comment: string;
     author: Types.ObjectId; // Reference to User schema
   }

   // Main Product schema with embedded Reviews
   export type ProductDocument = Product & Document;
   @Schema({ timestamps: true })
   export class Product {
     @Prop({ required: true })
     name: string;

     @Prop({ unique: true })
     sku: string;

     @Prop()
     description: string;

     @Prop({ type: [{ type: Schema.Types.ObjectId, ref: 'User' }] })
     authors: Types.ObjectId[]; // Array of user IDs who contributed

     @Prop({ type: [ProductReview], default: [] })
     reviews: ProductReview[]; 
   }

   export const ProductSchema = SchemaFactory.createForClass(Product);
   ```

